// Determine: fresh job OR revision of an existing clip
let youtube_url = '', clip_count = 3, watermark = '@MemesAdda';
let run_id = '', isRevision = false;
let revisionClipIndex = 1, revisionInstructions = '', iteration = 1;

// ── Path A: Sheet trigger ────────────────────────────────────────────────────
try {
  const sheet = $items('📋 Trigger: New Clipping Row');
  if (sheet.length > 0 && (sheet[0].json.youtube_url || sheet[0].json['YouTube URL'])) {
    youtube_url = sheet[0].json.youtube_url || sheet[0].json['YouTube URL'] || '';
    clip_count  = Number(sheet[0].json.clip_count || 3);
    watermark   = sheet[0].json.watermark || '@MemesAdda';
    run_id      = Date.now().toString();
    isRevision  = false;
    const sd = $getWorkflowStaticData('global');
    sd[run_id] = { youtube_url, clip_count, watermark, clips: {}, iteration: 0 };
  }
} catch(e) {}

// ── Path B: Form (fresh) ─────────────────────────────────────────────────────
if (!youtube_url) {
  try {
    const form = $items('🎯 Form: New Clip Job');
    if (form.length > 0 && form[0].json['YouTube URL']) {
      youtube_url = form[0].json['YouTube URL'];
      clip_count  = Number(form[0].json['Number of Clips (1–4)']) || 3;
      watermark   = form[0].json['Channel Watermark'] || '@MemesAdda';
      run_id      = Date.now().toString();
      isRevision  = false;
      const sd = $getWorkflowStaticData('global');
      sd[run_id] = { youtube_url, clip_count, watermark, clips: {}, iteration: 0 };
    }
  } catch(e) {}
}

// ── Path C: Revision form ────────────────────────────────────────────────────
if (!youtube_url) {
  try {
    const rev = $items('✏️ Form: Revise Clip');
    if (rev.length > 0 && rev[0].json['Clip Job ID (from Telegram)']) {
      run_id               = rev[0].json['Clip Job ID (from Telegram)'].trim();
      revisionClipIndex    = Number(rev[0].json['Clip Number to Revise (1, 2, 3...)']) || 1;
      revisionInstructions = rev[0].json['What should change?'] || '';
      isRevision           = true;
      // Load state
      const sd = $getWorkflowStaticData('global');
      const prev = sd[run_id] || {};
      youtube_url = prev.youtube_url || '';
      clip_count  = prev.clip_count  || 3;
      watermark   = prev.watermark   || '@MemesAdda';
      iteration   = (prev.clips?.[revisionClipIndex]?.iteration || 0) + 1;
      if (!prev.clips) prev.clips = {};
      if (!prev.clips[revisionClipIndex]) prev.clips[revisionClipIndex] = { iteration: 0, history: [] };
      prev.clips[revisionClipIndex].iteration = iteration;
      prev.clips[revisionClipIndex].history   = [...(prev.clips[revisionClipIndex].history || []), revisionInstructions];
      sd[run_id] = prev;
    }
  } catch(e) {}
}

clip_count = Math.max(1, Math.min(4, Number(clip_count) || 3));

if (!youtube_url || !/^https?:\/\//.test(youtube_url)) {
  throw new Error('No valid YouTube URL found. Please provide a URL or a valid Clip Job ID.');
}
if (iteration > 8) throw new Error('Maximum revision limit (8) reached for this clip.');

return [{ json: {
  youtube_url, clip_count, watermark, run_id,
  isRevision, revisionClipIndex, revisionInstructions, iteration
} }];

// Build the python script command with revision constraints if applicable
const { youtube_url, clip_count, watermark, run_id, isRevision, revisionClipIndex, revisionInstructions, iteration } = $('🔀 Route: New Job or Clip Revision').first().json;

// Build extra constraint argument for the script
let extraArgs = '';
if (isRevision && revisionInstructions) {
  // Pass revision as an env variable — script will pick it up
  extraArgs = `CLIP_REVISION_TARGET=${revisionClipIndex} CLIP_REVISION_INSTRUCTIONS='${revisionInstructions.replace(/'/g, '').slice(0, 300)}'`;
}

return [{
  json: {
    youtube_url, clip_count, watermark, run_id, isRevision,
    revisionClipIndex, revisionInstructions, iteration,
    extraArgs
  }
}];

// Parse metadata and split into one item per clip
const buf  = Buffer.from($input.first().binary.data.data, 'base64');
const meta = JSON.parse(buf.toString('utf-8'));

if (!meta || meta.length === 0) {
  throw new Error('metadata.json is empty — no clips were produced by the script.');
}

const { run_id, watermark, isRevision, revisionClipIndex, iteration } = $('🔀 Route: New Job or Clip Revision').first().json;

// Update static data with latest clip results
const sd = $getWorkflowStaticData('global');
if (sd[run_id]) {
  if (!sd[run_id].clips) sd[run_id].clips = {};
  meta.forEach((clip, i) => {
    const clipNum = i + 1;
    sd[run_id].clips[clipNum] = {
      ...((sd[run_id].clips[clipNum]) || {}),
      title:      clip.title,
      caption:    clip.caption,
      hashtags:   clip.hashtags,
      start_time: clip.start_time,
      end_time:   clip.end_time,
      clip_path:  clip.clip_path
    };
  });
}

return meta.map((clip, i) => ({
  json: {
    clip_num:   i + 1,
    clip_total: meta.length,
    clip_path:  clip.clip_path,
    title:      clip.title      || `Clip ${i + 1}`,
    caption:    clip.caption    || '',
    hashtags:   clip.hashtags   || '#shorts #viral',
    start_time: clip.start_time || '',
    end_time:   clip.end_time   || '',
    run_id, watermark, isRevision,
    iteration:  isRevision ? iteration : 1
  }
}));

